// One-bit sequential circuit. The circuit is a multiplexer with a delay: the
// output is the input after a fixed delay, independent of the input signal
// itself.
module TopModule(input clock, input a, output reg p, output reg q);
  reg [1:0] s;
  always @(posedge clock) begin
    s <= {s[0], a};
    p <= s[1];
    q <= s[0];
  end
endmodule

