// The sequential circuit implements the truth table:
//
//   a -> p on rising edge, q on falling edge
//
// Which can be summarized as:
//
//   p = a AND NOT(clock)
//   q = a AND clock
//
module TopModule(input clock, input a, output p, output q);
    reg p_reg, q_reg;
    always @(posedge clock) p_reg <= a & ~clock;
    always @(negedge clock) q_reg <= a & clock;
    assign p = p_reg;
    assign q = q_reg;
endmodule

