// One-bit sequential circuit, determined by the simulation waveforms.
module TopModule(input clock, input a, output reg p, output reg q);
  reg [1:0] state;
  always @(posedge clock) begin
    case (state)
      2'b00: begin p <= 1'b0; q <= 1'b0; if (a) state <= 2'b01; end
      2'b01: begin p <= 1'b1; q <= 1'b0; if (!a) state <= 2'b10; end
      2'b10: begin p <= 1'b1; q <= 1'b1; if (a) state <= 2'b11; end
      2'b11: begin p <= 1'b0; q <= 1'b1; if (!a) state <= 2'b00; end
    endcase
  end
  initial state <= 2'b00;
endmodule

// Sequential circuit as described in the simulation waveforms. The p and q
// outputs are registered, i.e. they track the value from the previous clock
// cycle.
module TopModule(input clock, input a, output reg p, output reg q);
    reg [1:0] state;
    always @(posedge clock) begin
        case (state)
            2'b00: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b01 : 2'b00; end
            2'b01: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b11 : 2'b00; end
            2'b10: begin p <= 1'b1; q <= 1'b0; state <= a ? 2'b11 : 2'b01; end
            2'b11: begin p <= 1'b1; q <= 1'b1; state <= a ? 2'b01 : 2'b10; end
        endcase
    end
endmodule

// One-bit sequential circuit. The register p and q is clocked on the
// positive edge of the clock signal. The output p is a delayed version
// of the input a, while the output q is a delayed version of p and a.
module TopModule(input clock, input a, output reg p, output reg q);
  reg [1:0] delay;
  always @(posedge clock) begin
    delay <= {delay[0], a};
    p <= delay[1];
    q <= {p, a};
  end
endmodule

